import React, { useState } from 'react';
import { useParams, Link } from 'react-router-dom';
import { courses } from '../data/courses';
import paymentModal from '../components/PaymentModal';
import Navbar from '../components/Navbar';

const CourseDetails = () => {
  const { id } = useParams();
  const [selectedCourse, setSelectedCourse] = useState(null);
  const course = courses.find(c => c.id === parseInt(id));

  if (!course) {
    return (
      <div className="bg-[#020617] min-h-screen text-white">
        <Navbar />
        <div className="flex items-center justify-center py-32 font-mono text-sm text-slate-500">
          Cours introuvable.
        </div>
      </div>
    );
  }

  return (
    <div className="bg-[#020617] min-h-screen text-white font-sans selection:bg-blue-500/30">
      <Navbar />

      <section className="max-w-3xl mx-auto px-8 py-16">
        <span className={`text-[10px] font-mono px-3 py-1 rounded-full ${course.isFree ? 'bg-emerald-500/10 text-emerald-400' : 'bg-blue-500/10 text-blue-400'}`}>
          {course.isFree ? 'GRATUIT' : 'PREMIUM'}
        </span>

        <h1 className="text-3xl md:text-4xl font-black mt-4 mb-4 bg-gradient-to-b from-white to-slate-500 bg-clip-text text-transparent">
          {course.title}
        </h1>
        <p className="text-slate-400 text-sm mb-10 max-w-xl">{course.description}</p>

        <div className="space-y-2 mb-10">
          <h3 className="text-xs font-mono uppercase text-slate-500 tracking-widest mb-3">Programme</h3>
          {course.lessons.map(lesson => (
            <div key={lesson.id} className="flex justify-between items-center bg-slate-950 border border-slate-900 rounded-lg p-4 hover:border-slate-700 transition">
              <span className="text-sm">{lesson.title}</span>
              <span>{lesson.locked ? '🔒' : '✅'}</span>
            </div>
          ))}
        </div>

        <div className="flex items-center justify-between bg-slate-950 border border-slate-900 rounded-xl p-6">
          <div>
            <span className="text-[10px] font-mono text-slate-500 uppercase tracking-widest block">Tarif</span>
            <span className="text-xl font-bold text-blue-400">
              {course.isFree ? 'Gratuit' : `${course.price.toLocaleString()} FCFA`}
            </span>
          </div>
          <button
            onClick={() => setSelectedCourse(course)}
            className="bg-blue-600 hover:bg-blue-500 px-8 py-3 rounded-lg text-xs font-bold uppercase tracking-wider transition"
          >
            {course.isFree ? 'Accéder au cours' : "Débloquer l'accès à vie"}
          </button>
        </div>
      </section>

      {selectedCourse && <PaymentModal course={selectedCourse} onClose={() => setSelectedCourse(null)} />}
    </div>
  );
};
export default CourseDetails;
